package io.github.chutian0610.jolt.bind;

import java.lang.reflect.Method;

/**
 * The POJO accessor convention, one home: which methods count as setters, and how a
 * setter/accessor name maps to its JSON property name. The no-annotations contract names
 * properties verbatim, so this convention IS the POJO mapping's interface — it is consumed
 * by the bind layer ({@code GenPlan}, {@code ReflectiveBinder}, {@code DirectBinder}) and
 * by jolt-gen's emitters and plan executor. Generation-time only: nothing here is named by
 * generated bytecode.
 */
public final class PojoSupport {

    private PojoSupport() {}

    /** The setter predicate: {@code setX}, void return, one parameter, public. */
    public static boolean isSetter(Method method) {
        return method.getName().startsWith("set")
                && method.getReturnType() == void.class
                && method.getParameterCount() == 1
                && java.lang.reflect.Modifier.isPublic(method.getModifiers());
    }

    /** {@code setX → x} — the JSON key a setter binds (derived from the exact name; a bare
     * "{@code set}" is not a usable setter key). */
    public static String setterKey(Method setter) {
        String mn = setter.getName();
        return Character.toLowerCase(mn.charAt(3)) + mn.substring(4);
    }

    /** {@code getX/isX → x} — the JSON property an accessor writes (a bare
     * "{@code get}"/"{@code is}" passes through as its own name). */
    public static String propertyName(String accessorName) {
        int prefix = accessorName.startsWith("is") ? 2 : 3;
        if (accessorName.length() <= prefix) {
            return accessorName;
        }
        return Character.toLowerCase(accessorName.charAt(prefix))
                + accessorName.substring(prefix + 1);
    }
}
